package cart

// Item represents a product in the cart
type Item struct {
	ID       string
	Name     string
	Price    float64
	Quantity int
}

// ShoppingCart holds items for purchase
type ShoppingCart struct {
	items map[string]*Item
}

// NewShoppingCart creates a fresh cart - a blank canvas for my work
func NewShoppingCart() *ShoppingCart {
	return &ShoppingCart{
		items: make(map[string]*Item),
	}
}

// AddItem introduces a new specimen to the collection
func (c *ShoppingCart) AddItem(id, name string, price float64, quantity int) {
	if existing, ok := c.items[id]; ok {
		existing.Quantity += quantity
		return
	}
	c.items[id] = &Item{
		ID:       id,
		Name:     name,
		Price:    price,
		Quantity: quantity,
	}
}

// RemoveItem excises an item completely
func (c *ShoppingCart) RemoveItem(id string) {
	delete(c.items, id)
}

// UpdateQuantity adjusts the dosage... I mean, quantity
func (c *ShoppingCart) UpdateQuantity(id string, quantity int) {
	if item, ok := c.items[id]; ok {
		if quantity <= 0 {
			delete(c.items, id)
			return
		}
		item.Quantity = quantity
	}
}

// GetItem retrieves a specific specimen
func (c *ShoppingCart) GetItem(id string) *Item {
	return c.items[id]
}

// GetItems returns all specimens in the collection
func (c *ShoppingCart) GetItems() []*Item {
	items := make([]*Item, 0, len(c.items))
	for _, item := range c.items {
		items = append(items, item)
	}
	return items
}

// GetTotal calculates the final cost of reanimation services
func (c *ShoppingCart) GetTotal() float64 {
	var total float64
	for _, item := range c.items {
		total += item.Price * float64(item.Quantity)
	}
	return total
}

// Clear purges all evidence... all items
func (c *ShoppingCart) Clear() {
	c.items = make(map[string]*Item)
}

// IsEmpty checks if the cart contains any specimens
func (c *ShoppingCart) IsEmpty() bool {
	return len(c.items) == 0
}

// ItemCount returns total quantity across all items
func (c *ShoppingCart) ItemCount() int {
	count := 0
	for _, item := range c.items {
		count += item.Quantity
	}
	return count
}
